import{_ as a,a as t,b as o,c as l,d as i,e as n,f as s,g as h}from"./chunks/autog2_4.DXO1QpAf.js";import{_ as p,c as u,o as d,al as r,j as c}from"./chunks/framework.CT7RwC5a.js";const T=JSON.parse('{"title":"ThunderFly Auto-G2 오토자이로","description":"","frontmatter":{},"headers":[],"relativePath":"ko/frames_autogyro/thunderfly_auto_g2.md","filePath":"ko/frames_autogyro/thunderfly_auto_g2.md"}'),b={name:"ko/frames_autogyro/thunderfly_auto_g2.md"};function m(f,e,g,_,y,k){return d(),u("div",null,e[0]||(e[0]=[r('<h1 id="thunderfly-auto-g2-오토자이로" tabindex="-1">ThunderFly Auto-G2 오토자이로 <a class="header-anchor" href="#thunderfly-auto-g2-오토자이로" aria-label="Permalink to &quot;ThunderFly Auto-G2 오토자이로&quot;">​</a></h1><p>The <em>ThunderFly Auto-G2</em> is an autopilot-controlled autogyro based on the Durafly™ Auto-G2 Gyrocopter RC model, with several parts of the original model substituted for 3D printable ones.</p><p><img src="'+a+'" alt="Auto-G2"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Auto-G2 autogyro’s airframe was originally developed by <a href="https://www.thunderfly.cz/" target="_blank" rel="noreferrer">ThunderFly</a> and has since evolved into the updated <a href="https://docs.thunderfly.cz/instruments/TF-G2" target="_blank" rel="noreferrer">TF-G2 platform</a>. Check out our site for more information on the current <a href="https://www.thunderfly.cz/tf-g2.html" target="_blank" rel="noreferrer">TF-G2 commercial airframe</a>.</p></div><p>All the added parts are available on <a href="https://github.com/ThunderFly-aerospace/Auto-G2" target="_blank" rel="noreferrer">GitHub</a> as an open-source project. Printed parts are designed in <a href="https://www.openscad.org/" target="_blank" rel="noreferrer">OpenSCAD</a>.</p><h2 id="수정-내역" tabindex="-1">수정 내역 <a class="header-anchor" href="#수정-내역" aria-label="Permalink to &quot;수정 내역&quot;">​</a></h2><p>Durafly Auto-G2는 원 디자인에는 CLARK-Y 프로파일을 가진 400mm 길이의 세 개의 블레이드 로터가 있습니다. 로터 헤드는 ROLL 축에서만 기울일 수 있습니다. 오토자이로는 방향타와 엘리베이터로 제어됩니다. Durafly Auto-G2 오토자이로 박스에는 오토자이로 폴리스티렌 본체, ESC, 모터 (아마 800kV), 4 개의 서보, 테일 에어 포일, 로터 센터 부품이있는 3 개의 블레이드, 와이어 섀시 및 프리 로테이터가 포함됩니다.</p><p>Durafly 모델의 수정 내역은 아래와 같습니다.</p><ul><li>자율 비행 기능 추가</li><li>두 개의 자유 축(피치, 롤)이 있는 로터 헤드</li><li>Two-blade rotor with safely breakable rotor plate</li><li>랜딩 기어 크기 증가</li></ul><h3 id="오토파일럿" tabindex="-1">오토파일럿 <a class="header-anchor" href="#오토파일럿" aria-label="Permalink to &quot;오토파일럿&quot;">​</a></h3><p>수정된 모델의 항공기의 중량은 매우 무겁습니다. Therefore a low-weight flight controller is recommended (e.g. <a href="./../flight_controller/holybro_pix32.html">Holybro pix32</a> or <a href="./../flight_controller/cuav_v5_nano.html">CUAV nano</a>).</p><p>The autopilot should be mounted on the bottom side of the autogyro on a 3D-printed damping pad. We have used the damping platform found on <a href="https://www.thingiverse.com/thing:160655" target="_blank" rel="noreferrer">thingiverse</a></p><h3 id="로터-헤드" tabindex="-1">로터 헤드 <a class="header-anchor" href="#로터-헤드" aria-label="Permalink to &quot;로터 헤드&quot;">​</a></h3><p>The rotor head is (compared to the original autogyro) modified so that it allows a motion in both roll and pitch axes. 헤드 로터는 오토자이로의 회전과 등반 제어가 모두 가능하게 되었습니다. Directional control of an autogyro by the rotor is possible even in the case of low airspeed compared to the original rudder and elevator control.</p><p>인쇄된 로터 헤드는 세 부분으로 구성됩니다. 바닥 부분은 M2.5 나사를 사용하여 원래 합판 철탑에 나사로 고정됩니다. 첫 번째 부품과 두 번째 부품 사이에있는 M3x35 나사는 피치 축 자유도를 제공하고, 두 번째 부품과 세 번째 부품 사이의 연결은 롤 축 자유도를 제공합니다. 후자의 축은 나사식 자동 잠금 너트가있는 M3x30 나사로 만들어집니다. 로터 쪽에서 스크류 헤드에는 면적이 넓은 와셔가 있습니다.</p><p>M3x50 고강도 나사로 만들어진 로터 축은 세 번째 부분을 통과합니다. 사용된 베어링은 623 2Z C3 SKF입니다. 이 부분의 끝에는 M2.5 나사를 통해 파일론의 바닥 부분에 위치한 서보에 부착된 볼로드가 있습니다. It is preferable to exchange these original servos for better quality ones as they are weak and in the original construction, they help each other.</p><p><img src="'+t+'" alt="Rotorhead"></p><h3 id="이중-날-로터" tabindex="-1">이중 날 로터 <a class="header-anchor" href="#이중-날-로터" aria-label="Permalink to &quot;이중 날 로터&quot;">​</a></h3><p>The original Durafly Auto-G2 autogyro has a three-blade rotor, which has been modified in this build to use a two-blade rotor. 수정의 주된 이유는 진동이 적고 조립이 간편하기 때문입니다. 인쇄된 중앙 부품은 중국산 Durafly 블레이드 또는 3D 인쇄 블레이드와 함께 사용하도록 설계되었습니다.</p><p>The rotor&#39;s central part consists of several components, which have the following roles:</p><ul><li>블레이드를 펄럭일 수 있습니다.</li><li>They have deformation zones that break upon impact with the ground. 덕분에 일반적으로 하나의 부품만 교체로 로터를 신속하게 수리 할 수 있습니다.</li><li>Easy setup of blades&#39; angle-of-attack.</li></ul><h4 id="hobbyking-로터-블레이드" tabindex="-1">HobbyKing 로터 블레이드 <a class="header-anchor" href="#hobbyking-로터-블레이드" aria-label="Permalink to &quot;HobbyKing 로터 블레이드&quot;">​</a></h4><p>원 블레이드와 함께 로터의 인쇄된 중앙 부분을 사용할 수 있습니다. These blades can be bought on <a href="https://hobbyking.com/en_us/duraflytm-auto-g-gyrocopter-821mm-replacement-main-blade-1pcs-bag.html" target="_blank" rel="noreferrer">HobbyKing</a>. Hobbyking blades differ in the position of the center of gravity, and it is therefore necessary to balance them properly.</p><h4 id="_3d-프린팅-로터-블레이드" tabindex="-1">3D 프린팅 로터 블레이드 <a class="header-anchor" href="#_3d-프린팅-로터-블레이드" aria-label="Permalink to &quot;3D 프린팅 로터 블레이드&quot;">​</a></h4><p>로터 블레이드를 인쇄할 수 있습니다.</p><p>The printed rotor blades are still under development, but preliminary tests show they are of better quality, mostly thanks to their precise shape and absence of longitudinal grooves. 그러나, 일부 제작 과정은 아직도 튜닝중입니다.</p><p><img src="'+o+'" alt="Blades assembly"></p><h4 id="균형-유지" tabindex="-1">균형 유지 <a class="header-anchor" href="#균형-유지" aria-label="Permalink to &quot;균형 유지&quot;">​</a></h4><p>Proper blade balance is very important to minimize vibrations. 블레이드는 무게 중심이 로터 축의 중앙에 위치하도록 균형을 맞추어야 합니다.</p><p>Printed blades are balanced in the production process, and there is no need to further balance them.</p><h3 id="릴리스-장치" tabindex="-1">릴리스 장치 <a class="header-anchor" href="#릴리스-장치" aria-label="Permalink to &quot;릴리스 장치&quot;">​</a></h3><p>If you want to launch an autogyro using a winch or if you want to launch it by towing, you need to print a release device. It is a small box equipped with a servo that pulls out the pin and releases the rope.</p><p>전체 부품은 오토자이로 본체 하단에있는 엔진 아래에 핫멜트 접착제를 사용하여 접착됩니다. 오토자이로가 로프로 견인되는 경우 엔진이 켜지지 않아야 합니다. 예를 들어, 릴리스 장치 스위치가 닫혀 있는 경우 트랜스미터에서 엔진 출력을 무효화 할 수 있습니다.</p><p><img src="'+l+'" alt="Release device"></p><h2 id="부품-목록" tabindex="-1">부품 목록 <a class="header-anchor" href="#부품-목록" aria-label="Permalink to &quot;부품 목록&quot;">​</a></h2><h3 id="전자-부품" tabindex="-1">전자 부품 <a class="header-anchor" href="#전자-부품" aria-label="Permalink to &quot;전자 부품&quot;">​</a></h3><ul><li>Autopilot (<a href="./../flight_controller/holybro_pix32.html">Holybro pix32</a>, <a href="./../flight_controller/cuav_v5_nano.html">CUAV nano</a>)</li><li>GPS (GPS Module NEO-6M, with patch antenna)</li><li>Airspeed sensor (<a href="https://www.sensirion.com/en/flow-sensors/differential-pressure-sensors/worlds-smallest-differential-pressure-sensor/" target="_blank" rel="noreferrer">SDP3x</a>)</li><li>Stronger servos as a substitution for the original ones (optional), (<a href="https://www.blue-bird-model.com/products_detail/411.htm" target="_blank" rel="noreferrer">BlueBird BMS-125WV</a>)</li><li>릴리스 장치용 추가 서보 (옵션)</li></ul><h3 id="기계-부품" tabindex="-1">기계 부품 <a class="header-anchor" href="#기계-부품" aria-label="Permalink to &quot;기계 부품&quot;">​</a></h3><ul><li>로터 헤드 베어링 (623 2Z C3)</li><li>Propeller (<a href="https://www.apcprop.com/product/10x7e/" target="_blank" rel="noreferrer">APC 10x7</a>)</li><li><a href="https://mpjet.com/shop/gb/prop-adapters/184-collet-prop-adapter-19-mm-4-mm-shaft-m629-standard.html" target="_blank" rel="noreferrer">Prop adapter</a></li></ul><h3 id="기판-부품" tabindex="-1">기판 부품 <a class="header-anchor" href="#기판-부품" aria-label="Permalink to &quot;기판 부품&quot;">​</a></h3><ul><li><p>로터 헤드:</p><ul><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/111_1001.stl" target="_blank" rel="noreferrer">Pylon end</a></li><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/111_1002.stl" target="_blank" rel="noreferrer">Pitch part</a></li><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/111_1003.stl" target="_blank" rel="noreferrer">Roll part</a></li></ul></li><li><p>로터:</p><ul><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/111_1008.stl" target="_blank" rel="noreferrer">center part washer top</a></li><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/111_1004.stl" target="_blank" rel="noreferrer">center part washer bottom</a></li><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/888_1001.stl" target="_blank" rel="noreferrer">center plate with deformation zones</a></li><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/111_1005.stl" target="_blank" rel="noreferrer">washers for setting AoA of blades</a></li><li><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/888_1002.stl" target="_blank" rel="noreferrer">Rotor nut</a></li></ul></li><li><p>로터 블레이드 (옵션)</p></li><li><p>자율비행장치 홀더</p></li><li><p><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/888_1010.stl" target="_blank" rel="noreferrer">Release device</a></p></li><li><p><a href="https://github.com/ThunderFly-aerospace/Auto-G2/blob/master/CAD/stl/888_1011.stl" target="_blank" rel="noreferrer">Front wheels</a></p></li></ul><h3 id="권장-예비-부품" tabindex="-1">권장 예비 부품 <a class="header-anchor" href="#권장-예비-부품" aria-label="Permalink to &quot;권장 예비 부품&quot;">​</a></h3><ul><li>Servos with improved quality (recommended <a href="https://www.blue-bird-model.com/products_detail/411.htm" target="_blank" rel="noreferrer">BlueBird BMS-125WV</a>, original servos are not very durable))</li><li>Propeller (<a href="https://www.apcprop.com/product/10x7e/" target="_blank" rel="noreferrer">APC 10x7</a>)</li><li>변형 영역이있는 로터 중앙 플레이트 (3D 인쇄)</li><li>Rotor blades (<a href="https://hobbyking.com/en_us/duraflytm-auto-g-gyrocopter-821mm-replacement-main-blade-1pcs-bag.html" target="_blank" rel="noreferrer">HobbyKing</a> or 3D printed)</li></ul><h2 id="비디오" tabindex="-1">비디오 <a class="header-anchor" href="#비디오" aria-label="Permalink to &quot;비디오&quot;">​</a></h2>',44),c("lite-youtube",{videoid:"YhXXSWz5wWs",title:"[ThunderFly] 3D printed autogyro rotor"},null,-1),r('<h2 id="변경-사진-갤러리" tabindex="-1">변경 사진 갤러리 <a class="header-anchor" href="#변경-사진-갤러리" aria-label="Permalink to &quot;변경 사진 갤러리&quot;">​</a></h2><p><img src="'+i+'" alt="Auto-G2 1"><img src="'+n+'" alt="Auto-G2 2"><img src="'+s+'" alt="Auto-G2 3"><img src="'+h+'" alt="Auto-G2 4"></p>',2)]))}const v=p(b,[["render",m]]);export{T as __pageData,v as default};
